import sys

def greet(name: str) -> str:
    """Returns the greeting string without a newline."""
    return f"Hello, {name}"

if __name__ == "__main__":
    if len(sys.argv) > 1:
        name = sys.argv[1]
        print(f"Hello, {name}!")
    else:
        print("Hello, World!")

import unittest
from greet import greet

class TestGreeting(unittest.TestCase):

    def test_default_greeting_function(self):
        # Test the function returning the default greeting without a newline
        self.assertEqual(greet("World"), "Hello, World")

    def test_named_greeting_function(self):
        # Test the function returning a specific name greeting without a newline
        self.assertEqual(greet("Ada"), "Hello, Ada")

if __name__ == '__main__':
    unittest.main()

